questionvariables.text:
/* Define all possible angle pairs with LaTeX strings */
pair1:"\\( \\angle a \\text{ and } \\angle e \\)";   /* correct */
pair2:"\\( \\angle b \\text{ and } \\angle f \\)";   /* correct */
pair3:"\\( \\angle c \\text{ and } \\angle g \\)";   /* correct */
pair4:"\\( \\angle d \\text{ and } \\angle h \\)";   /* correct */

pair5:"\\( \\angle a \\text{ and } \\angle b \\)";   /* incorrect */
pair6:"\\( \\angle c \\text{ and } \\angle d \\)";   /* incorrect */
pair7:"\\( \\angle e \\text{ and } \\angle f \\)";   /* incorrect */
pair8:"\\( \\angle g \\text{ and } \\angle h \\)";   /* incorrect */
pair9:"\\( \\angle a \\text{ and } \\angle c \\)";   /* incorrect */
pair10:"\\( \\angle b \\text{ and } \\angle d \\)";  /* incorrect */

/* Make correct and incorrect pools */
correct_answer:[pair1,pair2,pair3,pair4];
incorrect_pool:[pair5,pair6,pair7,pair8,pair9,pair10];

/* Randomly select 3 incorrect */
incorrect_answers:rand_selection(incorrect_pool,3);

/* Combine into answer list with true/false */
answer_list:append(
   makelist([x,true],x,correct_answer),
   makelist([x,false],x,incorrect_answers)
);

/* Shuffle for display */
ta:random_permutation(answer_list);
